import { cva } from "@lynstack/class-recipe";
import type { VariantsOf } from "@lynstack/class-recipe";

export const badgeVariants = cva({
  base: "inline-flex rounded-sm px-1.5 animate-in fade-in",
  variants: {
    tone: {
      danger: "bg-danger text-danger-foreground",
      neutral: "bg-muted text-foreground",
    },
    density: {
      comfortable: "text-sm",
      compact: "text-xs",
    },
  },
  defaultVariants: { tone: "neutral" },
});

export type BadgeTone = NonNullable<VariantsOf<typeof badgeVariants>["tone"]>;

import type { ComponentProps } from "react";

import { useSettings } from "#/lib/settings/settings-context";
import type { BadgeTone } from "./badge-variants";
import { badgeVariants } from "./badge-variants";

export function Badge({
  className,
  tone,
  ...props
}: ComponentProps<"span"> & { readonly tone?: BadgeTone }) {
  const { density } = useSettings();
  return (
    <span className={badgeVariants({ tone, density, className })} {...props} />
  );
}

/**
 * Shows a short status next to other content.
 *
 * @category display
 * @packageDocumentation
 */

export { Badge } from "./badge";
export type { BadgeTone } from "./badge-variants";
